from pathlib import Path
from datetime import datetime
import base64
import shutil
import py_compile
import subprocess
import sys

ROOT=Path.cwd()
REQUIRED=[ROOT/'src/enrichment/profiles.py',ROOT/'src/scoring/research_scoring.py']
missing=[str(p) for p in REQUIRED if not p.exists()]
if missing:
    print('エラー：clinic-list-filter-complete フォルダで実行してください。')
    for p in missing: print(' -',p)
    raise SystemExit(1)

stamp=datetime.now().strftime('%Y%m%d_%H%M%S')
backup=ROOT/('code_backup_research_v251_'+stamp)
backup.mkdir(parents=True,exist_ok=False)

PAYLOADS={'src/enrichment/profiles.py': '', 'src/scoring/research_scoring.py': '', 'verify_research_v251.py': '', 'rerun_latest_hp_job_v251.py': '', 'export_research_v251_results.py': ''}

targets=[ROOT/rel for rel in PAYLOADS]
for p in targets:
    if p.exists():
        dst=backup/p.relative_to(ROOT)
        dst.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(p,dst)

try:
    for rel,encoded in PAYLOADS.items():
        p=ROOT/rel
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_bytes(base64.b64decode(encoded))
    for rel in ['src/enrichment/profiles.py','src/scoring/research_scoring.py','verify_research_v251.py','rerun_latest_hp_job_v251.py','export_research_v251_results.py']:
        py_compile.compile(str(ROOT/rel),doraise=True)
    (ROOT/'VERSION_RESEARCH').write_text('2.5.1-research\n',encoding='utf-8')
except Exception as e:
    print('適用中にエラーが発生したため、バックアップから戻します。')
    for p in targets:
        src=backup/p.relative_to(ROOT)
        if src.exists():
            p.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(src,p)
    print('エラー:',repr(e))
    raise SystemExit(1)

print('v25.1 を適用しました。')
print('1. 年齢推定：院長本人ブロックを優先し、卒業年は卒業表現の直前年を優先。')
print('   例：1960年医学部卒業。1963年に渡米 → 1960年を卒業年として扱います。')
print('2. 集客施策：オンライン診療終了/休止/中止の明記がある場合は加点しません。')
print('3. 制作会社：Doctors File / WordPress / EPARK / Caloo / Google / SNS等を制作会社扱いしません。')
print('   DR.BRIDGE等の実際の制作会社リンクは従来どおり判定します。')
print('4. 内視鏡：美容外科等の「内視鏡下〜」だけでは消化器内視鏡カテゴリにしません。')
print('   胃カメラ・大腸内視鏡・消化管内視鏡・ポリープ等は従来どおり対象です。')
print('5. v24/v25の治療カテゴリ優先順位、昼枠、HPランク、Maps連携は維持します。')
print('SQLite / UUID / Maps取込結果 / Comdesk元データは変更していません。')
print('バックアップ:',backup.name)

print('\n確認テストを実行します...')
result=subprocess.run([sys.executable,str(ROOT/'verify_research_v251.py')])
if result.returncode!=0:
    print('確認テストが失敗しました。50件再調査はまだ実行しないでください。')
    raise SystemExit(result.returncode)
print('\nv25.1 適用 + 確認テスト完了です。')
print('\n直前と同じHP調査ジョブを v25.1 で自動再調査します...')
rerun=subprocess.run([sys.executable,str(ROOT/'rerun_latest_hp_job_v251.py')])
if rerun.returncode!=0:
    print('再調査を完了できませんでした。アプリが起動中なら停止して、rerun_latest_hp_job_v251.py を再実行してください。')
    raise SystemExit(rerun.returncode)
print('\n結果CSVを自動作成します...')
export=subprocess.run([sys.executable,str(ROOT/'export_research_v251_results.py')])
if export.returncode!=0:
    print('再調査は完了していますが、CSV出力だけ失敗しました。export_research_v251_results.py を再実行してください。')
    raise SystemExit(export.returncode)
print('\n=== v25.1 再調査まで完了 ===')
print('出力CSV:', (ROOT/'hp_research_results_v251.csv').resolve())
